<script setup lang="ts">import {Plus,Trash2,Upload} from 'lucide-vue-next';import type { ProductImage } from '~/types/product';const props=defineProps<{product?:any}>();const emit=defineEmits<{saved:[id:string]}>();const {data:categories}=await useFetch('/api/admin/categories',{transform:(r:any)=>r.data});const f=reactive({name:'',slug:'',sku:'',categoryId:'',price:0,stock:0,lowStockThreshold:5,shortDescription:'',description:'',isActive:true,isFeatured:false,specifications:[] as {key:string;value:string}[],images:[] as ProductImage[]});const loading=ref(false),error=ref(''),uploading=ref(false);watch(()=>props.product,p=>{if(p)Object.assign(f,{...p,categoryId:p.categoryId||p.category?.id,specifications:Object.entries(p.specifications||{}).map(([key,value])=>({key,value:String(value)})),images:p.images||[]})},{immediate:true});watch(()=>f.name,v=>{if(!props.product)f.slug=v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')});async function upload(e:Event){const files=Array.from((e.target as HTMLInputElement).files||[]);if(f.images.length+files.length>6){error.value='Maksimal 6 foto.';return}uploading.value=true;try{for(const file of files){const r:any=await $fetch('/api/admin/uploads/presign',{method:'POST',body:{filename:file.name,contentType:file.type,size:file.size}});await $fetch(r.data.uploadUrl,{method:'PUT',body:file,headers:{'Content-Type':file.type}});f.images.push({url:r.data.publicUrl,storageKey:r.data.key,alt:f.name||file.name,isCover:f.images.length===0})}}catch(e:any){error.value=e.data?.statusMessage||'Upload foto gagal.'}finally{uploading.value=false}}function removeImage(i:number){f.images.splice(i,1);if(f.images[0])f.images[0].isCover=true}async function save(){error.value='';loading.value=true;try{const body={...f,sku:f.sku.toUpperCase(),specifications:Object.fromEntries(f.specifications.filter(x=>x.key).map(x=>[x.key,x.value])),images:f.images.map((x,i)=>({...x,alt:x.alt||f.name,isCover:i===0,sortOrder:i}))};const r:any=await $fetch(props.product?`/api/admin/products/${props.product.id}`:'/api/admin/products',{method:props.product?'PUT':'POST',body});emit('saved',r.data.id)}catch(e:any){error.value=e.data?.statusMessage||e.data?.message||'Produk gagal disimpan.'}finally{loading.value=false}}</script>
<template><form class="product-form" @submit.prevent="save"><section class="panel block"><h2>Informasi dasar</h2><div class="form-grid"><div><label class="label">Nama produk *</label><input v-model="f.name" class="field" required></div><div><label class="label">Slug *</label><input v-model="f.slug" class="field" required></div><div><label class="label">SKU *</label><input v-model="f.sku" class="field" required></div><div><label class="label">Kategori *</label><select v-model="f.categoryId" class="field" required><option value="" disabled>Pilih kategori</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Harga jual *</label><input v-model.number="f.price" class="field" type="number" min="0" required></div><div><label class="label">Stok {{product?'saat ini':'awal'}} *</label><input v-model.number="f.stock" class="field" type="number" min="0" required><small v-if="product" class="muted">Perubahan otomatis dicatat sebagai penyesuaian.</small></div><div><label class="label">Batas stok menipis *</label><input v-model.number="f.lowStockThreshold" class="field" type="number" min="0" required></div></div><div><label class="label">Deskripsi pendek</label><input v-model="f.shortDescription" class="field" maxlength="220"></div><div><label class="label">Deskripsi lengkap</label><textarea v-model="f.description" class="field" rows="5" maxlength="5000"/></div><div class="checks"><label><input v-model="f.isActive" type="checkbox"> Produk aktif</label><label><input v-model="f.isFeatured" type="checkbox"> Produk unggulan</label></div></section><section class="panel block"><div class="block-head"><h2>Spesifikasi</h2><button class="btn btn-outline" type="button" @click="f.specifications.push({key:'',value:''})"><Plus :size="16"/>Tambah</button></div><div v-if="!f.specifications.length" class="muted">Belum ada spesifikasi.</div><div v-for="(s,i) in f.specifications" :key="i" class="spec-row"><input v-model="s.key" class="field" placeholder="Contoh: Ukuran"><input v-model="s.value" class="field" placeholder="Contoh: 45 × 65 cm"><button type="button" aria-label="Hapus" @click="f.specifications.splice(i,1)"><Trash2 :size="17"/></button></div></section><section class="panel block"><h2>Foto produk</h2><p class="muted">JPG, PNG, atau WebP. Maksimal 5 MB per gambar dan 6 gambar.</p><label class="btn btn-outline upload"><Upload :size="17"/>{{uploading?'Mengunggah…':'Pilih foto'}}<input type="file" accept="image/jpeg,image/png,image/webp" multiple hidden @change="upload"></label><div class="images"><div v-for="(img,i) in f.images" :key="img.url"><NuxtImg :src="img.url" :alt="img.alt"/><span v-if="i===0">Cover</span><button type="button" @click="removeImage(i)"><Trash2 :size="16"/></button></div></div></section><p v-if="error" class="error">{{error}}</p><button class="btn btn-primary save" :disabled="loading">{{loading?'Menyimpan…':'Simpan produk'}}</button></form></template>
<style scoped>.product-form{display:grid;gap:1rem}.block{padding:1.3rem;display:grid;gap:1rem}.block h2{font-size:1rem;margin:0}.block-head{display:flex;justify-content:space-between;align-items:center}.checks{display:flex;gap:1.5rem}.spec-row{display:grid;grid-template-columns:1fr 1fr 44px;gap:.5rem}.spec-row button{border:0;background:none;color:var(--danger)}.images{display:flex;flex-wrap:wrap;gap:.7rem}.images>div{position:relative}.images img{width:120px;height:90px;object-fit:cover;border-radius:9px}.images span{position:absolute;left:.3rem;bottom:.4rem;background:white;padding:.2rem .4rem;border-radius:5px;font-size:.65rem}.images button{position:absolute;right:.3rem;top:.3rem;background:white;border:0;border-radius:6px;padding:.25rem}.save{justify-self:end;min-width:180px}@media(max-width:600px){.spec-row{grid-template-columns:1fr 44px}.spec-row input:nth-child(2){grid-row:2;grid-column:1}.spec-row button{grid-row:1/3;grid-column:2}.checks{display:grid}}</style>
